// @vitest-environment node
import { describe, expect, it } from "vitest";
import { decryptContent, deriveBoxKeys, derivePinKeys, encryptContent } from "@/lib/textboxCrypto";

// Generated by aravindrpillai.com-BE/textbox/crypto.py (derive_open_keys + encrypt_content).
// If this test fails, the browser and server derivations have drifted apart.
const PY_BOX_ID = "d8410f8f81a58520cd3b713e05ebc63e15953ab416d2d313129e5b694adb45da";
const PY_CONTENT = "v1:9W+r7G/80XpNi5HotYqu3ouC+/jwgkqrNfXfIKwCmdHpdlCzihExS8FiNK/8GA==";

describe("textboxCrypto", () => {
  it("matches the server-side derivation (legacy migration)", async () => {
    const box = await deriveBoxKeys("  Hello-Box ");
    expect(box.boxId).toBe(PY_BOX_ID);
    expect(await decryptContent(box.openKey, box.boxId, false, PY_CONTENT)).toBe("<p>héllo 👋</p>");
  });

  it("binds content to box and lock state, and PIN keys differ", async () => {
    const box = await deriveBoxKeys("hello-box");
    const other = await deriveBoxKeys("other-box");
    const ct = await encryptContent(box.openKey, box.boxId, false, "secret");
    await expect(decryptContent(box.openKey, box.boxId, true, ct)).rejects.toThrow();
    await expect(decryptContent(box.openKey, other.boxId, false, ct)).rejects.toThrow();

    const p1 = await derivePinKeys(box, "1234");
    const p1again = await derivePinKeys(box, "1234");
    const p2 = await derivePinKeys(box, "1235");
    const pOther = await derivePinKeys(other, "1234");
    expect(p1.pinToken).toMatch(/^[0-9a-f]{64}$/);
    expect(p1.pinToken).toBe(p1again.pinToken);
    expect(p2.pinToken).not.toBe(p1.pinToken);
    expect(pOther.pinToken).not.toBe(p1.pinToken); // same PIN, different box -> different token

    const locked = await encryptContent(p1.lockKey, box.boxId, true, "locked secret");
    expect(await decryptContent(p1again.lockKey, box.boxId, true, locked)).toBe("locked secret");
    await expect(decryptContent(p2.lockKey, box.boxId, true, locked)).rejects.toThrow();
    await expect(decryptContent(box.openKey, box.boxId, true, locked)).rejects.toThrow();
  }, 30_000);
});
